    syllabusCodes: ["PT-01"],
    statement: `Texto: "Morar só por prazer" (mesmo texto-base da questão anterior).

O texto possui características típicas de uma reportagem porque apresenta`,
    options: [
      { key: "A", text: `relatos de episódios passados`, isCorrect: false, explanation: `Alternativa incorreta — ver comentário da questão para a justificativa completa.` },
      { key: "B", text: `comparações entre opiniões opostas`, isCorrect: false, explanation: `Alternativa incorreta — ver comentário da questão para a justificativa completa.` },
      { key: "C", text: `termos técnicos de circulação restrita`, isCorrect: false, explanation: `Alternativa incorreta — ver comentário da questão para a justificativa completa.` },
      { key: "D", text: `depoimentos de especialistas no assunto`, isCorrect: true, explanation: `O texto traz falas atribuídas ao antropólogo Gilberto Velho e à psicanalista Junia de Vilhena, caracterizando o gênero reportagem pela presença de depoimentos de especialistas. Núcleo do código PT-01 (compreensão de textos de gêneros variados, incluindo reconhecimento de características do gênero).` },
      { key: "E", text: `dados estatísticos de pesquisas realizadas`, isCorrect: false, explanation: `Alternativa incorreta — ver comentário da questão para a justificativa completa.` },
    ],
