    updatedAt: "2026-08-20T00:00:00.000Z",
    subjectSlug: "portugues",
    topicSlug: "pt-01-compreensao-textos",
    syllabusCodes: ["PT-01"],
    statement: `Texto: "Morar só por prazer" (mesmo texto-base).

Segundo a opinião da psicanalista entrevistada, morar sozinho pode ser considerado um comportamento`,
    options: [
      { key: "A", text: `altruísta`, isCorrect: false, explanation: `Alternativa incorreta — ver comentário da questão para a justificativa completa.` },
      { key: "B", text: `corajoso`, isCorrect: false, explanation: `Alternativa incorreta — ver comentário da questão para a justificativa completa.` },
      { key: "C", text: `comodista`, isCorrect: false, explanation: `Alternativa incorreta — ver comentário da questão para a justificativa completa.` },
      { key: "D", text: `benéfico`, isCorrect: true, explanation: `A psicanalista Junia de Vilhena afirma que ter uma casa só para si é 'muito saudável para o crescimento pessoal', caracterizando o comportamento como benéfico. Núcleo do código PT-01 (compreensão de textos).` },
      { key: "E", text: `comunicativo`, isCorrect: false, explanation: `Alternativa incorreta — ver comentário da questão para a justificativa completa.` },
    ],
    difficulty: "medio",
    source: { origin: "real", banca: "CESGRANRIO", orgao: "BR DISTRIBUIDORA", cargo: `Técnico(a) de Administração e Controle Júnior`, ano: 2013, numero: "3", cadernoUrl: "https://eticaconcursos.com.br/provas/arquivos/prova/cesgranrio-2013-br-distribuidora-tecnico-de-administracao-e-controle-junior-prova.pdf" },
    version: 1,
