    subjectSlug: "especificas",
    topicSlug: "ac-16-gestao-compras",
    syllabusCodes: ["AC-16"],
    statement: `Conforme prevê o Regulamento Licitatório da Petrobras, nos casos de emergência, quando caracterizada a urgência de atendimento de situação que possa ocasionar prejuízo ou comprometer a segurança de pessoas, obras, serviços, equipamentos e outros bens, a licitação será`,
    options: [
      { key: "A", text: `obrigatória`, isCorrect: false, explanation: `Alternativa incorreta — ver comentário da questão para a justificativa completa.` },
      { key: "B", text: `dispensada`, isCorrect: true, explanation: `[ATENÇÃO — LEGISLAÇÃO DESATUALIZADA: baseada no Decreto nº 2.745/1998 (Regulamento do Procedimento Licitatório Simplificado da Petrobras), já revogado. O conceito de dispensa de licitação por emergência é semelhante ao previsto nas leis atuais (Lei 14.133/2021, art. 75; Lei 13.303/2016, art. 29), mas os dispositivos legais específicos mudaram. Marcada sob_conferência.] Mapeada em AC-16 (7.3 legislação de licitações).` },
      { key: "C", text: `exigida`, isCorrect: false, explanation: `Alternativa incorreta — ver comentário da questão para a justificativa completa.` },
      { key: "D", text: `inexigida`, isCorrect: false, explanation: `Alternativa incorreta — ver comentário da questão para a justificativa completa.` },
      { key: "E", text: `desconsiderada`, isCorrect: false, explanation: `Alternativa incorreta — ver comentário da questão para a justificativa completa.` },
    ],
    difficulty: "medio",
    source: { origin: "real", banca: "CESGRANRIO", orgao: "TRANSPETRO", cargo: `Técnico(a) de Suprimento de Bens e Serviços Júnior - Administração`, ano: 2012, numero: "42", cadernoUrl: "https://arquivos.qconcursos.com/prova/arquivo_prova/28599/cesgranrio-2012-transpetro-tecnico-de-suprimentos-de-bens-e-servicos-junior-administracao-prova.pdf" },
    version: 1,
