    subjectSlug: "especificas",
    topicSlug: "ac-16-gestao-compras",
    syllabusCodes: ["AC-16"],
    statement: `A modalidade de licitação entre pessoas físicas ou jurídicas, do ramo pertinente ao objeto, em número mínimo de três licitantes, inscritas ou não no registro cadastral da Petrobras, é a(o)`,
    options: [
      { key: "A", text: `Tomada de preço`, isCorrect: false, explanation: `Alternativa incorreta — ver comentário da questão para a justificativa completa.` },
      { key: "B", text: `Concorrência`, isCorrect: false, explanation: `Alternativa incorreta — ver comentário da questão para a justificativa completa.` },
      { key: "C", text: `Convite`, isCorrect: true, explanation: `[ATENÇÃO — LEGISLAÇÃO DESATUALIZADA: a modalidade 'Convite', como descrita (mínimo de três licitantes), existia no regime da Lei nº 8.666/1993 e no Regulamento da Petrobras vigente em 2012 — já revogados. A Lei nº 14.133/2021 não prevê mais a modalidade Convite. Marcada sob_conferência — não usar sem adaptação/confirmação de que as modalidades vigentes (Lei 14.133/2021: concorrência, concurso, leilão, pregão, diálogo competitivo) foram consideradas.] Mapeada em AC-16 (7.3 legislação de licitações).` },
      { key: "D", text: `Leilão`, isCorrect: false, explanation: `Alternativa incorreta — ver comentário da questão para a justificativa completa.` },
      { key: "E", text: `Concurso`, isCorrect: false, explanation: `Alternativa incorreta — ver comentário da questão para a justificativa completa.` },
    ],
    difficulty: "medio",
    source: { origin: "real", banca: "CESGRANRIO", orgao: "TRANSPETRO", cargo: `Técnico(a) de Suprimento de Bens e Serviços Júnior - Administração`, ano: 2012, numero: "43", cadernoUrl: "https://arquivos.qconcursos.com/prova/arquivo_prova/28599/cesgranrio-2012-transpetro-tecnico-de-suprimentos-de-bens-e-servicos-junior-administracao-prova.pdf" },
    version: 1,
