    difficulty: "medio",
    source: { origin: "real", banca: "CESGRANRIO", orgao: "TRANSPETRO", cargo: `Técnico(a) de Suprimento de Bens e Serviços Júnior - Administração`, ano: 2012, numero: "47", cadernoUrl: "https://arquivos.qconcursos.com/prova/arquivo_prova/28599/cesgranrio-2012-transpetro-tecnico-de-suprimentos-de-bens-e-servicos-junior-administracao-prova.pdf" },
    version: 1,
