export const ALL_QUESTIONS: Question[] = [...AUTHORED_QUESTIONS, ...REAL_QUESTIONS];

/** Vincula uma questão à aula (se existir) do mesmo tópico — usado para o link "Ver aula relacionada"
 * no card de questão. Só cobre questões cujo `topicSlug` corresponde ao `slug` de uma aula já escrita. */
const lessonSlugByTopic = new Map(ALL_LESSONS.map((l) => [l.topicSlug, l.slug]));
export const QUESTION_LESSON_SLUG = new Map<string, string>(
  ALL_QUESTIONS.filter((q) => lessonSlugByTopic.has(q.topicSlug)).map((q) => [q.id, lessonSlugByTopic.get(q.topicSlug)!]),
);

export const QUESTION_COUNT_BY_SUBJECT = ALL_QUESTIONS.reduce<Record<string, number>>((acc, q) => {
  acc[q.subjectSlug] = (acc[q.subjectSlug] ?? 0) + 1;
  return acc;
}, {});

export function getQuestionsBySubject(subjectSlug: string): Question[] {
  return ALL_QUESTIONS.filter((q) => q.subjectSlug === subjectSlug);
}

export function getQuestionsBySyllabusCode(code: string): Question[] {
  return ALL_QUESTIONS.filter((q) => q.syllabusCodes.includes(code));
}
